tape( 'the function evaluates the inverse complementary error function for `x` on the interval `[1.9999..8,2]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var i;
	var e;
	var ulps;

	expected = x7.expected;
	x = x7.x;

	ulps = 24;
	for ( i = 0; i < x.length; i++ ) {
		y = erfcinvf( x[ i ] );
		e = f32( expected[ i ] );
		if ( e === null ) {
			e = NINF;
		}
		t.strictEqual( isAlmostSameValue( y, e, ulps ), true, 'within '+ulps+' ULPs. x: '+x[i]+'. y: '+y+'. E: '+e );
	}
	t.end();
});
